(5741185, 835453, 78891, '<td valign="top">Nice touch, and nice that you opened the bible to an appropriate section of the bible. The theme of Relion really comes through in this photo. Good Job.</td>', 'Nice touch, and nice that you opened the bible to an appropriate section of the bible. The theme of Relion really comes through in this photo. Good Job.', '2009-11-25 07:28:48.000000', NULL, 1),
(5741188, 835359, 78891, '<td valign="top">If the caption didn''t state that photography is thier religion, religion is a theme that I wouldn''t have got from the photo alone ... also, I find a lot of the streaks to be distracting ... maybe it''s just me ...</td>', 'If the caption didn''t state that photography is thier religion, religion is a theme that I wouldn''t have got from the photo alone ... also, I find a lot of the streaks to be distracting ... maybe it''s just me ...', '2009-11-25 07:35:55.000000', NULL, 1),
(5741189, 835495, 78891, '<td valign="top">Nice photo, interested in how you got the shadow to be different than the object apparently casting the shadow, within the rules of basic editing, without layers and masks in photoshop. But nice photo.</td>', 'Nice photo, interested in how you got the shadow to be different than the object apparently casting the shadow, within the rules of basic editing, without layers and masks in photoshop. But nice photo.', '2009-11-25 07:38:59.000000', NULL, 1),
