(5747161, 835365, 112004, '<td valign="top">To dark alittle more light</td>', 'To dark alittle more light', '2009-11-30 17:57:05.000000', NULL, 1),
(5747162, 835315, 112004, '<td valign="top">nice idea little to bright</td>', 'nice idea little to bright', '2009-11-30 17:57:38.000000', NULL, 1),
(5747210, 834614, 18197, '<td valign="top">Powerful image. Love the B&amp;W. Stark. Disturbing. Well done!</td>', 'Powerful image. Love the B&W. Stark. Disturbing. Well done!', '2009-11-30 18:47:37.000000', NULL, 1),
(5747211, 835137, 18197, '<td valign="top">Among best in show. Subject is a terrific fit. B&amp;W was inspired. Great clarity, focus, contrast. My top pick!</td>', 'Among best in show. Subject is a terrific fit. B&W was inspired. Great clarity, focus, contrast. My top pick!', '2009-11-30 18:47:40.000000', NULL, 1),
(5747212, 835258, 18197, '<td valign="top">I like the lens distortion here. It reinforces the religious overtones of building a monument to God. The processing which highlights the construction details is very very good. It feels solid, somehow, like you would want your faith to be a solid presence in your life.</td>', 'I like the lens distortion here. It reinforces the religious overtones of building a monument to God. The processing which highlights the construction details is very very good. It feels solid, somehow, like you would want your faith to be a solid presence in your life.', '2009-11-30 18:47:47.000000', NULL, 1),
(5747213, 835315, 18197, '<td valign="top">Gutsy entry ... incredible image ... not to everyone''s taste ... powerful!</td>', 'Gutsy entry ... incredible image ... not to everyone''s taste ... powerful!', '2009-11-30 18:47:52.000000', NULL, 1),
(5747215, 835378, 18197, '<td valign="top">A well executed vision of religion as a saccharine force. I deeply dislike this kind of sugary image (no protein here), but cannot find a better example in this challenge. 9 from me ... in spite of my prejudices.</td>', 'A well executed vision of religion as a saccharine force. I deeply dislike this kind of sugary image (no protein here), but cannot find a better example in this challenge. 9 from me ... in spite of my prejudices.', '2009-11-30 18:48:05.000000', NULL, 1),
(5747299, 835137, 81530, '<td valign="top">I wish I had taken a horizontal version as well. I only shot vertically, and this is much better. Awesome shot.</td>', 'I wish I had taken a horizontal version as well. I only shot vertically, and this is much better. Awesome shot.', '2009-11-30 19:32:12.000000', NULL, 1),
(5747424, 835259, 106349, '<td valign="top">Looks a little crooked. Nice colors, though.</td>', 'Looks a little crooked. Nice colors, though.', '2009-11-30 20:59:00.000000', NULL, 1),
